#include <stdio.h>

int main() {
    int q[5];
    int front = 0, rear = 0;
    q[rear++] = 7;
    q[rear++] = 8;
    q[rear++] = 9;
    while (front < rear) {
        printf("%d\n", q[front++]);
    }
    return 0;
}
